// ============================================================
//  WhatsApp - Lote Córdoba (vía WAHA)
//  Edita SOLO la sección "config" según tu entorno.
//  Documentación: whatsapp/README.md
// ============================================================
const config = {
  wahaUrl: 'http://localhost:3000',   // WAHA local (mismo host)
  apiKey: 'waha-dev-key-2026',        // = WAHA_API_KEY de whatsapp/waha/.env
  session: 'default',                 // nombre de sesión creada en el dashboard de WAHA
  dataUrl: 'https://pmachadojulio.pages.dev/data/prospects_crm.json',
  delayMs: 30000,                     // pausa entre mensajes (recomendado >= 25 s)
  maxEnviar: 20,                      // límite por corrida (empezá con 10-20)
  soloConTelefono: true,              // solo contactos que tienen teléfono
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const normalizePhone = (raw) => {
  if (!raw) return null;
  let n = String(raw).replace(/\D/g, '');
  if (!n.startsWith('54')) n = '54' + n;   // código de país Argentina
  n = n.replace(/^540/, '54');             // quitar 0 tras el 54
  if (n.length < 11 || n.length > 13) return null;
  return n + '@c.us';
};

const saludo = (p) => {
  const contacto = String(p.contacto || '').split('/')[0].split('(')[0].trim().split(' ')[0];
  const stop = ['Dirección', 'Equipo', 'Direc', 'Estudio', 'Casa', 'Atelier'];
  const nombre = contacto && !stop.includes(contacto) ? contacto : (p.empresa || '');
  return `Hola ${nombre},`;
};

const mensaje = (p) => {
  const base = p.categoria && /Arquitectura/i.test(p.categoria)
    ? 'https://jcmachado.com/obra/monoblocks/'
    : 'https://jcmachado.com/obra/ascenso-corazon/';
  return [
    `${saludo(p)}`,
    'Soy Julio César Machado, pintor al óleo de Córdoba.',
    'Te quería acercar mi trabajo y ofrecerte un catálogo sin compromiso.',
    `Podés ver una muestra acá: ${base}`,
    'Si te interesa, te mando por acá las obras disponibles y medidas.',
    '¡Gracias por el tiempo!',
  ].join('\n');
};

const http = this.helpers.httpRequest;
const data = await http({ method: 'GET', url: config.dataUrl, json: true });
const prospects = Array.isArray(data) ? data : (data.prospects || []);

const filtrados = prospects.filter((p) => {
  if (!p || typeof p !== 'object') return false;
  if (config.soloConTelefono && !p.telefono) return false;
  return true;
});

const yaVistos = new Set();
let enviados = 0;
const fallas = [];

for (const p of filtrados) {
  if (enviados >= config.maxEnviar) break;
  const chatId = normalizePhone(p.telefono);
  if (!chatId || yaVistos.has(chatId)) continue;
  yaVistos.add(chatId);
  try {
    await http({
      method: 'POST',
      url: `${config.wahaUrl}/api/sendText`,
      headers: { 'X-Api-Key': config.apiKey },
      body: { session: config.session, chatId, text: mensaje(p) },
      json: true,
    });
    enviados++;
  } catch (e) {
    fallas.push({ empresa: p.empresa || '(sin nombre)', error: String(e && e.message || e).slice(0, 120) });
  }
  if (enviados < config.maxEnviar) await sleep(config.delayMs);
}

return [{
  json: {
    totalEncontrados: filtrados.length,
    enviados,
    maxEnviar: config.maxEnviar,
    fallas: fallas.length,
    detalleFallas: fallas.slice(0, 10),
  },
}];
